UPDATE CFG_PROJECTS SET PROJECT_NAME=COALESCE(:name,PROJECT_NAME),TIMEZONE=COALESCE(:timezone,TIMEZONE),DEFAULT_POOL=COALESCE(:default_pool,DEFAULT_POOL),MAX_RUNNING_TASKS=COALESCE(:max_running_tasks,MAX_RUNNING_TASKS),ENVIRONMENT_TYPE=:environment_type,ENVIRONMENT_NAME=COALESCE(:environment_name,ENVIRONMENT_NAME),GOVERNANCE=:governance,SCHEMA_CHECK_SCHEDULE=CASE WHEN CAST(:schema_check_schedule AS varchar) IS NULL THEN SCHEMA_CHECK_SCHEDULE WHEN CAST(:schema_check_schedule AS varchar)='none' THEN NULL ELSE CAST(:schema_check_schedule AS varchar) END,SCHEMA_CHECK_ON_DEMAND=COALESCE(CAST(:schema_check_on_demand AS varchar),SCHEMA_CHECK_ON_DEMAND) WHERE PROJECT_CODE=:code
